  <div style="flex:1;min-width:0;display:flex;flex-direction:column;gap:22px"><div${A("rating")} style="display:flex;align-items:center;gap:14px">${star(Math.round(+c.rating||0))}<span style="font:600 24px/1 var(--sans)">${esc(c.rating)}.0</span><span style="width:1px;height:22px;background:var(--line)"></span><span class="lb" style="font-size:22px">회원님이 직접 남긴 후기</span></div><div${A("review")} style="font:400 ${fs}px/1.75 var(--sans);letter-spacing:-.02em;color:var(--muted);word-break:keep-all">${esc(c.review).replace(/\*([^*]+)\*/g,'<b style="font-weight:600;color:var(--ink);background:linear-gradient(transparent 55%,var(--accent-soft) 55%)">$1</b>')}</div></div>
