 <div${A("keywords")} style="display:grid;grid-template-columns:1fr 1fr;gap:12px 20px;margin-top:${tall?36:20}px">${c.keywords.slice(0,tall?6:4).map((k,i)=>`<div style="display:flex;align-items:center;gap:14px;font:600 24px/1.2 var(--sans);color:var(--ink)"><span style="width:38px;height:38px;border-radius:50%;flex:none;display:flex;align-items:center;justify-content:center;background:${i?"var(--sunken)":"var(--accent)"};color:${i?"var(--ink)":"#fff"}">${chkS(20)}</span>${esc(k)}</div>`).join("")}</div>
