T.wideNotice={n:"가로 공지",cat:"notice",m:"pulse",shape:"l",d:"매장 TV·키오스크 공지",sx:NOTICE_SX,f(H,W){const c=C,k=Math.min(1.2,H/1080),rs=c.rows.slice(0,H>1200?6:5);
 return `<div style="position:absolute;inset:${Math.round(80*k)}px 96px;display:grid;grid-template-columns:0.9fr 1.1fr;gap:${Math.round(80*k)}px">
  <div style="display:flex;flex-direction:column"><div style="display:flex;gap:18px;align-items:center"><span class="tag on" style="height:${Math.round(56*k)}px;font-size:${Math.round(24*k)}px">NOTICE</span><span class="cap"${A("date")} style="font-size:${Math.round(26*k)}px">${esc(c.date)}</span></div>
   <h1 class="hl"${A("headline")} style="margin-top:${Math.round(50*k)}px;font-size:${Math.round(110*k)}px">${rich(c.headline)}</h1>${c.sub?`<p class="sub"${A("sub")} style="margin-top:${Math.round(24*k)}px;font-size:${Math.round(34*k)}px">${esc(c.sub)}</p>`:""}
   <div style="margin-top:auto">${mk(false,Math.round(56*k))}</div></div>
  <div style="display:flex;flex-direction:column;justify-content:center;gap:${Math.round(26*k)}px"><div class="card" style="padding:${Math.round(12*k)}px ${Math.round(52*k)}px">${rs.map((r,i)=>{const hi=isStar(r);return `<div class="row"${A("rows",i)} style="padding:${Math.round(32*k)}px 0"><span class="lb" style="font-size:${Math.round(32*k)}px">${esc(plain(r.label))}</span><span style="text-align:right"><span style="font:600 ${Math.round(46*k)}px/1 var(--sans);letter-spacing:-.02em;color:${hi?"var(--accent)":"var(--ink)"}">${esc(r.value)}</span>${r.note?`<span class="lb" style="display:block;font-size:${Math.round(24*k)}px;margin-top:8px">${esc(r.note)}</span>`:""}</span></div>`}).join("")}</div>
   <div style="display:flex;justify-content:space-between;align-items:center;gap:24px"><span class="lb"${A("footnote")} style="font-size:${Math.round(28*k)}px">${esc(c.footnote)}</span>${qrMini(Math.round(100*k))}</div></div></div>`}};

T.wideReview={n:"가로 후기",cat:"review",m:"pulse",shape:"l",d:"블로그 썸네일 · 후기",f(H,W){const c=C,k=Math.min(1.2,H/1080),cu=P("cut")||DEF_CUT,q=c.quotes[0]||"",D=Math.min(Math.round(H*1.02),1080),CH=Math.min(Math.round(H*.94),1000);
 return `<div style="position:absolute;left:${Math.round(-D*.26)}px;top:${Math.round(H*.12)}px;width:${D}px;height:${D}px;border-radius:50%;background:radial-gradient(circle at 34% 30%,var(--accent-light) 0%,var(--accent) 38%,var(--accent-deep) 85%);box-shadow:0 60px 120px var(--accent-glow)"></div>
 <div${A("photoCut")} style="position:absolute;left:${Math.round(-W*.02)}px;bottom:0;width:${Math.round(W*.42)}px;height:${CH}px;background:${U(cu)} center bottom/contain no-repeat"></div>
 <div style="position:absolute;right:96px;top:${Math.round(80*k)}px;bottom:${Math.round(80*k)}px;width:${Math.round(W*.45)}px;display:flex;flex-direction:column">
  <div style="display:flex;justify-content:space-between;align-items:center">${mk(false,Math.round(48*k))}<span class="cap" style="color:var(--accent-strong);font-size:${Math.round(24*k)}px">MEMBER REVIEW</span></div>
  <div${A("quotes",0)} style="margin-top:auto;position:relative"><div style="font:900 ${Math.round(220*k)}px/.6 var(--display);color:var(--accent);height:${Math.round(90*k)}px">“</div><p style="margin:0;font:600 ${fitLines(q,Math.round(W*.44),Math.round(84*k),48)}px/1.25 var(--sans);letter-spacing:-.04em;word-break:keep-all">${rich(q)}</p></div>
  <div${A("rating")} style="display:flex;align-items:center;gap:16px;margin-top:${Math.round(34*k)}px">${star(Math.round(+c.rating||0),null,Math.round(32*k))}<span style="font:700 ${Math.round(34*k)}px/1 var(--display)">${esc(c.rating)}.0</span></div>
  <div style="margin-top:auto;display:flex;justify-content:space-between;align-items:flex-end;gap:24px;padding-top:${Math.round(30*k)}px;border-top:1px solid var(--line)"><div${A("name")} style="min-width:0"><div style="font:700 ${Math.round(38*k)}px/1.15 var(--sans);letter-spacing:-.03em">${esc(c.name)}</div><div class="lb"${A("creds")} style="font-size:${Math.round(24*k)}px;margin-top:8px">${esc(lines(c.creds)[0]||"")}</div></div><div${A("ccta")} style="display:flex;align-items:center;gap:14px;height:${Math.round(84*k)}px;padding:0 12px 0 32px;border-radius:999px;background:var(--accent);color:#fff;font:700 ${Math.round(26*k)}px/1 var(--sans);flex:none;box-shadow:0 20px 40px var(--accent-glow)">${esc(c.ccta)}<span style="width:${Math.round(60*k)}px;height:${Math.round(60*k)}px;border-radius:50%;background:#fff;color:var(--accent);display:flex;align-items:center;justify-content:center">${arrowS(Math.round(30*k))}</span></div></div></div>`}};

